"use client";

import { createContext, useContext } from "react";
import { houseMotionProfile } from "./profiles/create-motion-profile";
import type { MotionProfile } from "./profiles/types";

export const MotionProfileContext =
  createContext<MotionProfile>(houseMotionProfile);

export function useMotionProfile(): MotionProfile {
  return useContext(MotionProfileContext);
}

"use client";

import { CustomEase } from "gsap/CustomEase";
import { gsap } from "gsap";
import { cubicBezierToGsap } from "./export-motion-profile";
import {
  GSAP_EASE_NAMES,
  NATIVE_GSAP_EASE_NAMES,
} from "./gsap-ease-names";
import { TWEEN_INTENTS, type MotionProfileData } from "./profiles/types";

let registeredSignature: string | null = null;
let pluginRegistered = false;

const customEasePlugin = CustomEase;

function profileEaseSignature(profile: MotionProfileData): string {
  return JSON.stringify(profile.easing);
}

export function registerMotionEases(profile: MotionProfileData) {
  if (typeof window === "undefined") {
    return;
  }

  if (!pluginRegistered) {
    gsap.registerPlugin(customEasePlugin);
    pluginRegistered = true;
  }

  const signature = profileEaseSignature(profile);
  if (registeredSignature === signature) {
    return;
  }

  for (const intent of TWEEN_INTENTS) {
    const name = GSAP_EASE_NAMES[intent];
    if (NATIVE_GSAP_EASE_NAMES.has(name)) {
      throw new Error(
        `Refusing to register ${name}. Semantic GSAP eases must not overwrite native names.`,
      );
    }
    customEasePlugin.create(name, cubicBezierToGsap(profile.easing[intent]));
  }

  registeredSignature = signature;
}

export function getMotionEaseRegistrationSignature() {
  return registeredSignature;
}

export function resetMotionEaseRegistration() {
  registeredSignature = null;
  pluginRegistered = false;
}

export { CustomEase, GSAP_EASE_NAMES, NATIVE_GSAP_EASE_NAMES };

import { serializeMotionProfile } from "./profiles/create-motion-profile";
import {
  DURATION_TOKENS,
  STAGGER_TOKENS,
  TWEEN_INTENTS,
  type CubicBezier,
  type MotionProfileData,
  type TweenIntent,
} from "./profiles/types";
import { GSAP_EASE_NAMES } from "./gsap-ease-names";

export function cubicBezierToCss(bezier: CubicBezier): string {
  return `cubic-bezier(${bezier[0]}, ${bezier[1]}, ${bezier[2]}, ${bezier[3]})`;
}

export function cubicBezierToGsap(bezier: CubicBezier): string {
  return `${bezier[0]},${bezier[1]},${bezier[2]},${bezier[3]}`;
}

export function motionProfileToCss(profile: MotionProfileData): string {
  const data = serializeMotionProfile(profile);
  const easeLines = TWEEN_INTENTS.map(
    (intent) => `  --ease-${intent}: ${cubicBezierToCss(data.easing[intent])};`,
  );
  const durationLines = DURATION_TOKENS.map(
    (token) => `  --duration-${token}: ${String(data.duration[token])}s;`,
  );
  const staggerLines = STAGGER_TOKENS.map(
    (token) => `  --stagger-${token}: ${String(data.stagger[token])}s;`,
  );

  return [":root {", ...easeLines, ...durationLines, ...staggerLines, "}"].join(
    "\n",
  );
}

export function motionProfileToMotionTs(profile: MotionProfileData): string {
  const data = serializeMotionProfile(profile);
  return `import { createMotionProfile } from "@cds/motion";

export const projectMotionProfile = createMotionProfile(${JSON.stringify(data, null, 2)});
`;
}

export function motionProfileToGsapRegistration(
  profile: MotionProfileData,
): Record<(typeof GSAP_EASE_NAMES)[TweenIntent], string> {
  const data = serializeMotionProfile(profile);
  return {
    [GSAP_EASE_NAMES.enter]: cubicBezierToGsap(data.easing.enter),
    [GSAP_EASE_NAMES.settle]: cubicBezierToGsap(data.easing.settle),
    [GSAP_EASE_NAMES.move]: cubicBezierToGsap(data.easing.move),
    [GSAP_EASE_NAMES.exit]: cubicBezierToGsap(data.easing.exit),
    [GSAP_EASE_NAMES.linear]: cubicBezierToGsap(data.easing.linear),
  };
}

export function motionProfileToJson(profile: MotionProfileData): string {
  return `${JSON.stringify(serializeMotionProfile(profile), null, 2)}\n`;
}

import type { CubicBezier, DurationToken, MotionProfileData, TweenIntent } from "./profiles/types";

export type ResolveTweenOptions = {
  intent?: TweenIntent;
  ease?: CubicBezier;
  duration?: number;
  durationToken?: DurationToken;
};

export function toMotionEase(
  ease: CubicBezier,
): [number, number, number, number] {
  return [ease[0], ease[1], ease[2], ease[3]];
}

export function resolveTween(
  profile: MotionProfileData,
  options: ResolveTweenOptions = {},
): { duration: number; ease: CubicBezier } {
  const intent = options.intent ?? "enter";
  return {
    duration:
      options.duration ??
      profile.duration[options.durationToken ?? "base"],
    ease: options.ease ?? profile.easing[intent],
  };
}

export const TWEEN_INTENTS = [
  "enter",
  "settle",
  "move",
  "exit",
  "linear",
] as const;

export const SPRING_INTENTS = ["pop"] as const;

export const DURATION_TOKENS = ["instant", "fast", "base", "slow"] as const;

export const STAGGER_TOKENS = ["tight", "normal", "expressive"] as const;

export type TweenIntent = (typeof TWEEN_INTENTS)[number];

export type SpringIntent = (typeof SPRING_INTENTS)[number];

export type DurationToken = (typeof DURATION_TOKENS)[number];

export type StaggerToken = (typeof STAGGER_TOKENS)[number];

export type CubicBezier = readonly [number, number, number, number];

export type SpringConfig = {
  type: "spring";
  stiffness: number;
  damping: number;
  mass: number;
  velocity?: number;
};

export type MotionProfileData = {
  easing: Record<TweenIntent, CubicBezier>;
  spring: Record<SpringIntent, SpringConfig>;
  duration: Record<DurationToken, number>;
  stagger: Record<StaggerToken, number>;
};

export type MotionProfileOverride = {
  easing?: Partial<Record<TweenIntent, CubicBezier>>;
  spring?: Partial<Record<SpringIntent, Partial<SpringConfig>>>;
  duration?: Partial<Record<DurationToken, number>>;
  stagger?: Partial<Record<StaggerToken, number>>;
};

export type MotionProfile = MotionProfileData & {
  ease: (intent: TweenIntent) => CubicBezier;
  springOf: (intent?: SpringIntent) => SpringConfig;
  durationOf: (token: DurationToken) => number;
  staggerOf: (token: StaggerToken) => number;
};

export class MotionProfileError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "MotionProfileError";
  }
}

import type { MotionProfileData } from "./types";

